#include "update_manifest.h"
#include <cassert>
#include <iostream>
int main(){UpdateManifest m;std::string good="{\"version\":\"0.2.3\",\"path\":\"/releases/0.2.3/AI1Emu.nro\",\"size\":12300000,\"sha256\":\""+std::string(64,'a')+"\"}";assert(parseUpdateManifest(good,m));assert(newerVersion(m.version,"0.2.2"));assert(!newerVersion("0.2.2","0.2.2"));assert(newerVersion("0.10.0","0.9.9"));assert(!parseUpdateManifest("{}",m));assert(!parseUpdateManifest(good+",\"version\":\"0.2.3\"",m));auto unsafe=good;unsafe.replace(unsafe.find("/releases/"),10,"http://bad");assert(!parseUpdateManifest(unsafe,m));auto large=good;large.replace(large.find("12300000"),8,"999999999");assert(!parseUpdateManifest(large,m));assert(newerVersion("0.5.10","0.5.9")&&!newerVersion("0.5.9","0.5.10")); std::cout<<"PASS: manifest size/hash/path/version validation and downgrade rejection\n"; UpdateManifest component;std::string componentJson="{\"version\":\"0.3.3\",\"path\":\"/releases/0.3.3/cores/mupen64plus-next.nro\",\"size\":45050221,\"sha256\":\""+std::string(64,'a')+"\"}";assert(parseUpdateManifest(componentJson,component,true));assert(!parseUpdateManifest(componentJson,component));assert(!parseUpdateManifest(componentJson+componentJson,component,true));
 std::string dsJson="{\"version\":\"0.3.5\",\"path\":\"/releases/0.3.5/cores/melonds.nro\",\"size\":12000000,\"sha256\":\""+std::string(64,'b')+"\"}";UpdateManifest ds;assert(parseUpdateManifest(dsJson,ds,false,true));assert(!parseUpdateManifest(dsJson,ds,true));assert(!parseUpdateManifest(dsJson,ds));assert(!parseUpdateManifest(dsJson,ds,true,true));
}
